auto simple = [] (int x, int y) {
    return x + y;
};
int result = simple(3, 4);

// Capture by Value
int factor = 10;
auto value_cap = [factor] (int x) {
    return factor * x;
};
// Use [=] to capture all local variables by value

// Capture by Reference
int counter = 0;
auto ref_cap = [&counter] () {
    counter++;
};
ref_cap(); // counter is now 1
// Use [&] to capture all local variables by reference

// Mutable Lambda (Allows modifying captured by value)
int count_start = 5;
auto decrement = [count_start] () mutable {
    count_start--;
    return count_start;
};

// Explicit Trailing Return Type (Required if return type is ambiguous)
auto complex_op = [] (int x) -> double {
    if (x < 0) return 0.0;
    return (double)x / 2.0;
};

// C++14 Generic Lambda
auto generic_printer = [] (auto item) {
    // 'item' is deduced (like a template)
    // Works for any type
};
